      {"text": "Оценка солёности пластовой воды по отклонению ПС", "claims": ["c3"], "hypothesis": false},
      {"text": "Отделение нефтеносных проницаемых пластов от непроницаемых при совместном чтении с сопротивлением", "claims": ["c6"], "hypothesis": false}
    ],
    "breaks": [
